// ---------- 全局状态 ----------
const state = {
  data: null,          // { meta, items }
  currentTab: '疾病速查',
  currentCategory: '全部系统',
  searchKeyword: '',
  selectedId: null
};

// ---------- DOM 引用 ----------
const els = {
  globalSearch: document.getElementById('globalSearch'),
  sidebar: document.getElementById('sidebar'),
  categorySelect: document.getElementById('categorySelect'),
  listSearch: document.getElementById('listSearch'),
  listCount: document.getElementById('listCount'),
  itemList: document.getElementById('itemList'),
  detailMeta: document.getElementById('detailMeta'),
  detailBody: document.getElementById('detailBody'),
  panelTitle: document.querySelector('.panel-title')
};

// ---------- 数据加载 ----------
async function loadData() {
  try {
    const res = await fetch('data/demo.json', { cache: 'no-store' });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    state.data = await res.json();
  } catch (e) {
    // file:// 双击打开时 fetch 通常被拦截，降级到内置兜底数据
    console.warn('fetch demo.json 失败，使用内置兜底数据：', e.message);
    state.data = FALLBACK_DATA;
  }
  initCategorySelect();
  renderList();
}

// ---------- 分类下拉 ----------
function initCategorySelect() {
  const cats = state.data.meta.categories || [];
  els.categorySelect.innerHTML = cats
    .map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`)
    .join('');
}

// ---------- 过滤逻辑 ----------
function getFilteredItems() {
  const kw = state.searchKeyword.trim().toLowerCase();
  return state.data.items.filter(it => {
    if (it.tab !== state.currentTab) return false;
    if (state.currentCategory !== '全部系统' && it.category !== state.currentCategory) return false;
    if (kw) {
      const hit = it.name.toLowerCase().includes(kw)
        || (it.abbr || '').toLowerCase().includes(kw)
        || (it.summary || '').toLowerCase().includes(kw);
      if (!hit) return false;
    }
    return true;
  });
}

// ---------- 列表渲染 ----------
function renderList() {
  const items = getFilteredItems();
  const unit = state.currentTab === '疾病速查' ? '种疾病' : '条内容';
  els.listCount.textContent = items.length === 0
    ? '0 条结果'
    : `${items.length} ${unit}`;
  els.panelTitle.textContent = state.currentTab;

  if (items.length === 0) {
    els.itemList.innerHTML = '<li class="list-empty">未找到匹配内容</li>';
    return;
  }

  els.itemList.innerHTML = items.map(it => `
    <li data-id="${escapeHtml(it.id)}" class="${it.id === state.selectedId ? 'active' : ''}">
      <span class="item-name">${escapeHtml(it.name)}</span>
      <span class="item-sub">${escapeHtml(it.category)} · ${escapeHtml(it.abbr || '')}</span>
    </li>
  `).join('');
}

// ---------- 详情渲染（优先 Markdown 决策卡片） ----------
function renderDetail() {
  const item = state.data.items.find(it => it.id === state.selectedId);
  if (!item) {
    els.detailMeta.textContent = '';
    els.detailBody.innerHTML = '<div class="empty-hint">请从左侧列表选择查看疾病速查决策卡片</div>';
    return;
  }
  els.detailMeta.textContent = `${item.category} · ${item.tab}`;
  if (item.card) {
    els.detailBody.innerHTML = `<div class="card">${renderMarkdown(item.card)}</div>`;
  } else if (item.detail) {
    // 旧格式兜底
    const sections = Object.entries(item.detail).map(([title, list]) => `
      <div class="detail-section">
        <h3>${escapeHtml(title)}</h3>
        <ul>${list.map(x => `<li>${escapeHtml(x)}</li>`).join('')}</ul>
      </div>
    `).join('');
    els.detailBody.innerHTML = `
      <div class="detail-header">
        <div class="detail-title">${escapeHtml(item.name)}<span class="detail-tag">${escapeHtml(item.abbr || '')}</span></div>
        <div class="detail-summary">${escapeHtml(item.summary || '')}</div>
      </div>
      ${sections}
    `;
  } else {
    els.detailBody.innerHTML = '<div class="empty-hint">该条目暂无详情内容</div>';
  }
  els.detailBody.scrollTop = 0;
}

// ---------- Markdown 子集渲染（决策卡片引擎） ----------
function renderMarkdown(md) {
  const lines = String(md).split('\n');
  let html = '';
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (/^\s*$/.test(line)) { i++; continue; }

    // 一级标题 + 英文副标
    if (/^#\s+/.test(line)) {
      const t = line.replace(/^#\s+/, '');
      const m = t.match(/^(.*?)（(.+?)）\s*$/) || t.match(/^(.*?)\s*\((.+?)\)\s*$/);
      if (m) html += `<h1 class="card-h1">${escapeHtml(m[1])}<span class="card-en">${escapeHtml(m[2])}</span></h1>`;
      else html += `<h1 class="card-h1">${escapeHtml(t)}</h1>`;
      i++; continue;
    }
    // 二级模块
    if (/^##\s+/.test(line)) {
      html += `<h2 class="card-h2">${escapeHtml(line.replace(/^##\s+/, ''))}</h2>`;
      i++; continue;
    }
    // 参考指南（灰度小字 + 虚线分割）
    if (/^>\s?/.test(line)) {
      let g = '';
      while (i < lines.length && /^>\s?/.test(lines[i])) { g += lines[i].replace(/^>\s?/, '') + ' '; i++; }
      html += `<div class="card-guide">${escapeHtml(g.trim())}</div>`;
      continue;
    }
    // 表格
    if (/^\|/.test(line)) {
      const tbl = [];
      while (i < lines.length && /^\|/.test(lines[i])) { tbl.push(lines[i]); i++; }
      html += buildTable(tbl);
      continue;
    }
    // 列表
    if (/^[-*]\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^[-*]\s+/.test(lines[i])) { items.push(lines[i].replace(/^[-*]\s+/, '')); i++; }
      html += '<ul class="card-ul">' + items.map(it => {
        const mm = it.match(/^\*\*(.+?)\*\*[:：]\s*(.*)$/);
        if (mm) return `<li><b>${escapeHtml(mm[1])}</b>：${escapeHtml(mm[2])}</li>`;
        return `<li>${escapeHtml(it)}</li>`;
      }).join('') + '</ul>';
      continue;
    }
    // 段落
    html += `<p>${escapeHtml(line)}</p>`;
    i++;
  }
  return html;
}

function buildTable(rows) {
  const parse = r => r.replace(/^\||\|$/g, '').split('|').map(s => s.trim());
  const head = parse(rows[0]);
  const data = rows.slice(2).map(parse); // 跳过表头与分隔行
  let h = '<table class="card-table"><thead><tr>' +
    head.map(c => `<th>${escapeHtml(c)}</th>`).join('') + '</tr></thead><tbody>';
  h += data.map(r => '<tr>' + r.map(c => `<td>${escapeHtml(c)}</td>`).join('') + '</tr>').join('');
  h += '</tbody></table>';
  return h;
}

// ---------- 工具函数 ----------
function escapeHtml(str) {
  return String(str == null ? '' : str)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

// ---------- 事件绑定 ----------
function bindEvents() {
  // 侧栏 Tab 切换
  els.sidebar.addEventListener('click', e => {
    const btn = e.target.closest('.tab-item');
    if (!btn) return;
    els.sidebar.querySelectorAll('.tab-item').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    state.currentTab = btn.dataset.tab;
    state.selectedId = null;
    // 同步分类下拉（当前分类在该 Tab 下可能无数据，重置为全部）
    state.currentCategory = '全部系统';
    els.categorySelect.value = '全部系统';
    renderList();
    renderDetail();
  });

  // 分类下拉
  els.categorySelect.addEventListener('change', () => {
    state.currentCategory = els.categorySelect.value;
    renderList();
  });

  // 左栏搜索
  els.listSearch.addEventListener('input', () => {
    state.searchKeyword = els.listSearch.value;
    if (els.globalSearch.value !== els.listSearch.value) {
      els.globalSearch.value = els.listSearch.value;
    }
    renderList();
  });

  // 顶栏全局搜索（与左栏搜索联动）
  els.globalSearch.addEventListener('input', () => {
    state.searchKeyword = els.globalSearch.value;
    if (els.listSearch.value !== els.globalSearch.value) {
      els.listSearch.value = els.globalSearch.value;
    }
    renderList();
  });

  // 列表点击 → 详情
  els.itemList.addEventListener('click', e => {
    const li = e.target.closest('li[data-id]');
    if (!li) return;
    state.selectedId = li.dataset.id;
    els.itemList.querySelectorAll('li').forEach(x => x.classList.remove('active'));
    li.classList.add('active');
    renderDetail();
  });

  // 字号切换
  document.querySelectorAll('.font-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.body.classList.remove('font-small', 'font-mid', 'font-large');
      document.body.classList.add('font-' + btn.dataset.size);
      document.querySelectorAll('.font-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    });
  });

  // 顶栏「速查提示」按钮
  document.getElementById('btnQuick').addEventListener('click', () => {
    alert('提示：左侧选择分类或直接搜索（支持拼音首字母，如 qttxy），点击条目即可查看详情。');
  });
}

// ---------- 启动 ----------
bindEvents();
loadData();
